^I^It.Run("Level2", func(t *testing.T) {
^I^I^It.Run("Level3", func(t *testing.T) {
^I^I^I^It.Log("deep")
^I^I^I})
^I^I})
^I^It.Run("Level2b", func(t *testing.T) { t.Skip("skip deep") })
^I})
^It.Run("Group With Spaces", func(t *testing.T) {})
