^Ifor _, n := range []string{"P1", "P2", "P3"} {
^I^In := n
^I^It.Run(n, func(t *testing.T) {
^I^I^It.Parallel()
^I^I^Itime.Sleep(10 * time.Millisecond)
^I^I^It.Logf("parallel %s done", n)
^I^I})
^I}
}

